entries[312751] = { ["name"] = "Clutch of Ha-Li", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"The brood of Ha-Li are comfortable in the blue skies of Pandaria, hunting unsuspecting prey.\"\nDrop:\nHa-Li\nZone:\nVale of Eternal Blossoms" }
entries[312752] = { ["name"] = "Freezing", ["text"] = "20 yd range\nInstant\nApplies Hoarfrost every 6 sec." }
entries[312753] = { ["name"] = "Hopecrusher Gargon", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Once the loyal mount of a House Briarbane lord, it turned on the lord and his retinue. Members of House Briarbane now whisper of a dark Gargon lying in wait even baiting venthyr who venture through the darker parts of the Chalice District of Revendreth.\"\nCovenant:\nVenthyr\nZone:\nRevendreth" }
entries[312754] = { ["name"] = "Battle Gargon Vrednic", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Prince Renathal's loyal gargon, Vrednic has been by his side for millennia. Adorned in his Sinvyr armor, Vrednic's mere presence instills terror to all those who lay eyes on him as he ushers his rider into battle.\"\nCovenant:\nVenthyr\nZone:\nRevendreth" }
entries[312756] = { ["name"] = "PH Phalynx", ["text"] = "1.5 sec cast\nSummons and dismisses this mount." }
entries[312758] = { ["name"] = "PH Epic Phalynx", ["text"] = "1.5 sec cast\nSummons and dismisses this mount." }
entries[312759] = { ["name"] = "Dreamlight Runestag", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Runestags are granted to those who have pledged their service to the Winter Queen and the Court of Night.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[312761] = { ["name"] = "Enchanted Dreamlight Runestag", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"The majestic runestags are capable of siphoning anima from the ambient light of Ardenweald with their elaborate antlers. The anima is used as nourishment and to power the runestag's speed and magic.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[312762] = { ["name"] = "Mawsworn Soulhunter", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Soulhunters are used to track wayward souls across the wastes that flee from their dark fates, and are one of the only creatures that feel comfortable traversing the maw.\"\nDrop:\nGorged Shadehound\nZone:\nThe Maw" }
entries[312763] = { ["name"] = "Darkwarren Hardshell", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"The Darkwarren Hardshell's chitin is sturdy enough to withstand mortar shells and dragon's fire. It will also conveniently consume anything lacking anima, if needed.\"\nAdventures:\nShadowlands" }
