entries[312940] = { ["name"] = "Shackle the Unworthy", ["text"] = "Covenant Ability\nInstant\nAdmonish your target for their past transgressions, reducing the damage they deal to you by 8% and dealing (186.578% of Attack Power) Arcane damage over 14 sec.\n\nWhile Shackle the Unworthy is active on an enemy, your direct-damage attacks that spend runes have a 100% chance to spread Shackle the Unworthy to a nearby enemy." }
entries[312941] = { ["name"] = "Elysian Decree", ["text"] = "Covenant Ability\nInstant\nPlace a Kyrian Sigil at the target location that activates after 2 sec.\n\nDetonates to deal (378% of Attack Power) Arcane damage and shatter up to 3 Lesser Soul Fragments from enemies affected by the sigil. Deals reduced damage beyond 5 targets." }
