entries[312946] = { ["name"] = "Kindred Spirits", ["text"] = "Covenant Ability\nInstant\nForm a bond with an ally. Every 1 min, you may empower the bond for 10 sec, granting you an effect based on your partner's role, and granting them an effect based on your role.\n\n[ Guardian : Tank\nKindred Protection\nProtect your bonded partner, redirecting 40% of damage they take to you, unless you fall below 20% health. ] [ Restoration : Healer\nKindred Focus\nFocus on your bonded partner, replicating 30% of all healing you deal onto them. /\n\nBalance, Feral\nDamager\nKindred Empowerment\nEnergize your bonded partner, granting them 20% of your damage as additional Arcane damage, healing, or absorption. ]" }
entries[312947] = { ["name"] = "Resonating Arrow", ["text"] = "Covenant Ability\nInstant\nFire a resonating arrow to the target location that deals (20% of Attack Power) Arcane damage to any enemy in the area, and fill the area with echoing anima for 10 sec. The effect causes your attacks to ignore line of sight to enemies in the area, and you have 30% increased critical strike chance against them.\n\nLeaving the area of echoing anima will still allow the hunter to ignore line of sight towards the enemy for 4 sec." }
entries[312950] = { ["name"] = "Radiant Spark", ["text"] = "Covenant Ability\nInstant\nConjure a radiant spark that causes (91.2% of Spell Power) Arcane damage instantly, and an additional (49.5% of Spell Power) damage over 10 sec.\n\nThe target takes 10% increased damage from your direct damage spells, stacking each time they are struck. This effect ends after 4 spells." }
entries[312951] = { ["name"] = "Weapons of Order", ["text"] = "Covenant Ability\nInstant\nBrewmaster\nFor the next 30 sec, your Mastery is increased by ( 0.924000025 * 10)%. Additionally, Keg Smash cooldown is reset instantly and enemies hit by Keg Smash take 8% increased damage from you for 10 sec, stacking up to 4 times.\n\nWindwalker\nFor the next 30 sec, your Mastery is increased by ( 2.3287499 * 10)%. Additionally, Rising Sun Kick reduces Chi costs by 1 for 5 sec, and Blackout Kick reduces the cooldown of affected abilities by an additional 1 sec.\n\nMistweaver\nFor the next 30 sec, your Mastery is increased by ( 6.92999983 * 10)%. Additionally, Essence Font cooldown is reset instantly and heals up to 6 nearby allies for (40% of Spell Power) health on channel start and end." }
entries[312952] = { ["name"] = "Divine Toll", ["text"] = "Covenant Ability\nInstant\nInstantly cast Holy Shock, Avenger's Shield, or Judgment on up to 5 targets within 30 yds (based on your current specialization). [ Retribution : Divine Toll's Judgment deals 100% increased damage ]" }
entries[312953] = { ["name"] = "Boon of the Ascended", ["text"] = "Covenant Ability\nInstant\nDraw upon the power of the Ascended for 10 sec, granting you access to Ascended Nova , replacing [ Shadow : Mind Flay /\n\nDiscipline, Holy\nSmite ] with Ascended Blast , and increasing movement speed by 50%.\n\nUpon expiration, releases an Ascended Eruption :\n\nExplode for up to (210% of Spell Power) Arcane damage to enemies and (159% of Spell Power) healing to allies within 15 yds, based on number of targets. Damage and healing increased by 3% for each stack of Boon of the Ascended." }
entries[312954] = { ["name"] = "Echoing Reprimand", ["text"] = "Covenant Ability\nInstant\nDeal (120% of Attack Power) Arcane damage to an enemy, extracting their anima to Animacharge a combo point for 45 sec.\n\nDamaging finishing moves that consume the same number of combo points as your Animacharge function as if they consumed 7 combo points.\n\nAwards 2 combo points." }
entries[312955] = { ["name"] = "Vesper Totem", ["text"] = "Covenant Ability\nInstant\nSummon a totem at the target location for 30 sec. Your next 3 damage spells or abilities will cause the totem to radiate (80% of Spell Power) Arcane damage to up to 6 enemies near the totem, and your next 3 healing spells will heal up to 6 allies near the totem for (91% of Spell Power) health.\n\nCasting this ability again while the totem is active will relocate the totem." }
entries[312956] = { ["name"] = "Scouring Tithe", ["text"] = "Covenant Ability\nInstant\nDeal (65% of Spell Power) Arcane damage instantly, and (108% of Spell Power) over 18 sec. If the enemy dies while affected by Scouring Tithe, you generate [ Affliction : 5 / Demonology : 5 /\n\nDestruction\n5 ] Soul Shards. If they survive, Scouring Tithe's cooldown is refreshed." }
entries[312957] = { ["name"] = "Spear of Bastion", ["text"] = "Covenant Ability\nInstant\nThrow a Kyrian spear at the target location, dealing (110% of Attack Power) Arcane damage instantly and an additional (120% of Attack Power) damage over 4 sec. Deals reduced damage beyond 5 targets.\n\nEnemies hit are tethered to Spear of Bastion's location for the duration.\n\nGenerates 25 Rage." }
